import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const o="/images/agent-proactive.webp",u=JSON.parse('{"title":"主动消息","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/proactive.md","filePath":"guide/agent/proactive.md","lastUpdated":1789295632000}'),l={name:"guide/agent/proactive.md"};function n(s,a,p,c,d,_){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="主动消息" tabindex="-1">主动消息 <a class="header-anchor" href="#主动消息" aria-label="Permalink to &quot;主动消息&quot;">​</a></h1><p>让角色主动找你聊天，而不只是等你开口。</p><h2 id="前提-时间感知" tabindex="-1">前提：时间感知 <a class="header-anchor" href="#前提-时间感知" aria-label="Permalink to &quot;前提：时间感知&quot;">​</a></h2><p>主动消息依赖<strong>时间感知</strong>（把当前北京时间告诉角色，会话设置中默认开启）。如果主动消息无法开启，先到「会话」标签页确认时间感知已打开。</p><h2 id="两种方式" tabindex="-1">两种方式 <a class="header-anchor" href="#两种方式" aria-label="Permalink to &quot;两种方式&quot;">​</a></h2><ul><li><strong>随机主动</strong>：会话静默 30 分钟后，角色会按北京时间的昼夜权重随机安排一次主动消息——白天和晚上都可能来，深夜概率更低。</li><li><strong>定时主动</strong>：角色可以自主创建、调整或取消最多 5 个定时计划，比如「每天早上叫你起床」。</li></ul><h2 id="管理定时计划" tabindex="-1">管理定时计划 <a class="header-anchor" href="#管理定时计划" aria-label="Permalink to &quot;管理定时计划&quot;">​</a></h2><p>「主动消息」标签页会列出当前所有定时计划，每个计划显示：</p><ul><li>描述（角色打算做什么）</li><li>状态：执行中 / 已暂停 / 已完成 / 已取消</li><li>下次执行时间</li><li>剩余次数（一次性计划会标注「一次性」，无限重复的计划不显示）</li></ul><p>你可以随时<strong>暂停、恢复或删除</strong>任意计划；过期的一次性计划无法恢复。</p><p>计划由角色自己维护——它会在对话中根据你们的约定调整计划，调整记录会体现在计划列表里。如果某次执行失败，会提示「上次执行失败，本次已跳过」。</p><p><img src="'+o+'" alt="主动消息"></p>',12)])])}const g=e(l,[["render",n]]);export{u as __pageData,g as default};
